1	#!/usr/bin/env node
2	// PostToolUse hook — forwards pipeline GitHub comments to Slack
3	'use strict';
4	
5	const https = require('https');
6	const fs    = require('fs');
7	const path  = require('path');
8	
9	const SLACK_TOKEN = process.env.SLACK_BOT_TOKEN;
10	
11	// Load project config
12	const configPath = path.join(process.cwd(), '.claude', 'maestro.json');
13	let _ai = {};
14	try { _ai = JSON.parse(fs.readFileSync(configPath, 'utf8')).ai || {}; } catch {}
15	const CHANNEL_ID  = _ai.slack_channel || '';
16	const REPO        = _ai.repo || '';
17	const THREADS_DIR = _ai.slack_threads_dir
18	  ? path.join(process.cwd(), ..._ai.slack_threads_dir.split('/'))
19	  : path.join(process.cwd(), ...(_ai.temp_root || '.TemporaryItems/Issues/pipeline').split('/'), 'slack-threads');
20	
21	setTimeout(() => process.exit(0), 9000);
22	
23	if (!SLACK_TOKEN || !CHANNEL_ID) {
24	  process.stderr.write('slack-notify: SLACK_BOT_TOKEN not set or slack_channel not configured in repo-map.json\n');
25	  process.exit(0);
26	}
27	
28	let raw = '';
29	process.stdin.setEncoding('utf8');
30	process.stdin.on('data', c => { raw += c; });
31	process.stdin.on('end', async () => {
32	  try { await run(raw); } catch (e) { process.stderr.write(`slack-notify error: ${e.message}\n`); }
33	  process.exit(0);
34	});
35	
36	// ---------------------------------------------------------------------------
37	// Triggers — issue comments, PR comments, PR-ready transitions
38	// ---------------------------------------------------------------------------
39	
40	const TRIGGERS = [
41	  { test: cmd => cmd.includes('gh issue comment'), type: 'issue_comment' },
42	  { test: cmd => cmd.includes('gh pr comment'),    type: 'pr_comment'   },
43	  { test: cmd => /\bgh pr ready\b/.test(cmd),      type: 'pr_ready'     },
44	];
45	
46	async function run(raw) {
47	  let data;
48	  try { data = JSON.parse(raw); } catch { return; }
49	
50	  if (data.tool_name !== 'Bash') return;
51	  const command = data.tool_input?.command || '';
52	  const trigger = TRIGGERS.find(t => t.test(command));
53	  if (!trigger) return;
54	
55	  const output = getOutput(data);
56	
57	  if (trigger.type === 'pr_ready') {
58	    await handlePrReady(command, output);
59	    return;
60	  }
61	
62	  // Require a GitHub URL in the output confirming the comment was posted
63	  const commentUrlMatch =
64	    output.match(/https:\/\/github\.com\/[^\s<>]+#issuecomment-\d+/) ||
65	    output.match(/https:\/\/github\.com\/[^\s<>]+#discussion_r\d+/);
66	  if (!commentUrlMatch) {
67	    process.stderr.write('slack-notify: no comment URL in gh output — command may have failed\n');
68	    return;
69	  }
70	  const commentUrl = commentUrlMatch[0];
71	
72	  const isIssue  = trigger.type === 'issue_comment';
73	  const refMatch = command.match(/gh (?:issue|pr) comment\s+([^\s"'\\]+)/);
74	  const refNum   = refMatch?.[1]?.match(/\d+/)?.[0] || '';
75	  const ghUrl    = isIssue
76	    ? `https://github.com/${REPO}/issues/${refNum}`
77	    : `https://github.com/${REPO}/pull/${refNum}`;
78	
79	  const body        = extractBody(command);
80	  const commentType = detectCommentType(body);
81	
82	  // For PR comments, try to extract the associated issue number for threading
83	  const issueNum = isIssue ? refNum : (extractIssueFromBody(body) || '');
84	
85	  const { text, blocks } = buildMessage(commentType, body, refNum, ghUrl, commentUrl, isIssue);
86	
87	  // Thread all events for the same issue together
88	  const threadTs = issueNum ? getThreadTs(issueNum) : null;
89	  const payload  = { channel: CHANNEL_ID, text, blocks };
90	  if (threadTs) payload.thread_ts = threadTs;
91	
92	  const postedTs = await postToSlack(payload);
93	  if (!threadTs && issueNum && postedTs) saveThreadTs(issueNum, postedTs);
94	}
95	
96	// ---------------------------------------------------------------------------
97	// PR ready handler
98	// ---------------------------------------------------------------------------
99	
100	async function handlePrReady(command, output) {
101	  const prNum =
102	    command.match(/\bgh pr ready\s+(\d+)/)?.[1] ||
103	    output.match(/pull\/(\d+)/)?.[1];
104	  if (!prNum) return;
105	  const prUrl = `https://github.com/${REPO}/pull/${prNum}`;
106	
107	  await postToSlack({
108	    channel: CHANNEL_ID,
109	    text:    `PR #${prNum} is ready for review`,
110	    blocks: [
111	      {
112	        type: 'section',
113	        text: { type: 'mrkdwn', text: `🎉  *PR #${prNum} — Ready for Review*\nThe AI delivery pipeline is done. This PR is open for human review.` },
114	        accessory: { type: 'button', text: { type: 'plain_text', text: 'Open PR' }, url: prUrl, style: 'primary' }
115	      },
116	      { type: 'context', elements: [{ type: 'mrkdwn', text: `\`${REPO}\`` }] }
117	    ]
118	  });
119	}
120	
121	// ---------------------------------------------------------------------------
122	// Comment type detection
123	// ---------------------------------------------------------------------------
124	
125	function detectCommentType(body) {
126	  const h = (body.match(/^#{1,3}\s+(.+)$/m)?.[1] || '').toLowerCase();
127	  if (h.includes('delivery pipeline') || h.includes('pipeline — complete') || h.includes('pipeline complete')) return 'pipeline_summary';
128	  if (h.includes('groomin'))                                                                                    return 'grooming';
129	  if (h.includes('challenger') || h.includes('spec review'))                                                   return 'challenger';
130	  if (h.includes('implementation') || h.includes('dev complete'))                                              return 'implementation';
131	  if (h.includes('lead review') || h.includes('code review') || h.includes('pr review'))                      return 'lead_review';
132	  if (/ qa\b/.test(h) || h.includes('quality assurance') || h.includes('test report'))                        return 'qa';
133	  return 'generic';
134	}
135	
136	// ---------------------------------------------------------------------------
137	// Message builder
138	// ---------------------------------------------------------------------------
139	
140	function buildMessage(commentType, body, num, ghUrl, commentUrl, isIssue) {
141	  switch (commentType) {
142	    case 'pipeline_summary': return buildPipelineSummary(body, num, ghUrl, commentUrl);
143	    case 'grooming':         return buildStageCard('🔍', 'Grooming complete',   body, num, ghUrl, commentUrl, isIssue, buildGroomingDetail);
144	    case 'challenger':       return buildStageCard('⚔️',  'Spec Review',         body, num, ghUrl, commentUrl, isIssue, buildChallengerDetail);
145	    case 'implementation':   return buildStageCard('⚙️',  'Implementation',      body, num, ghUrl, commentUrl, isIssue, null);
146	    case 'lead_review':      return buildStageCard('👀', 'Lead Review',          body, num, ghUrl, commentUrl, isIssue, buildReviewDetail);
147	    case 'qa':               return buildStageCard('🧪', 'QA Report',            body, num, ghUrl, commentUrl, isIssue, buildQADetail);
148	    default:                 return buildGenericCard(body, num, ghUrl, commentUrl, isIssue);
149	  }
150	}
151	
152	// ---------------------------------------------------------------------------
153	// Pipeline summary — header + markdown table of stages
154	// ---------------------------------------------------------------------------
155	
156	function buildPipelineSummary(body, issueNum, issueUrl, commentUrl) {
157	  const title = body.match(/^#{1,3}\s+(.+)$/m)?.[1]?.trim() || 'Delivery Pipeline — Complete';
158	
159	  const prMatch     = body.match(/\*\*PR:\*\*\s*\[#(\d+)\]\(([^)]+)\)/);
160	  const statusMatch = body.match(/\*\*Status:\*\*\s*([^\n|*]+)/);
161	  const prNum   = prMatch?.[1];
162	  const prUrl   = prMatch?.[2];
163	  const status  = statusMatch?.[1]?.trim() || 'READY FOR REVIEW';
164	  const isReady = status.includes('READY');
165	
166	  // Build the markdown table from the stage table in the comment body
167	  const tableRows  = parseMarkdownTable(body);
168	  const tableLines = [
169	    '| Stage | Status | Notes |',
170	    '|---|---|---|',
171	    ...tableRows.map(([stage = '', result = '', notes = '']) => {
172	      const notesClean = (notes && notes !== '—') ? notes.trim() : '—';
173	      return `| ${stage.trim()} | ${result.trim()} | ${notesClean} |`;
174	    })
175	  ];
176	
177	  // Follow-up tickets
178	  const followupMatch = body.match(/\*\*Follow-up[^:]*:\*\*\s*(.+)/);
179	  const followup = followupMatch?.[1]?.trim() || 'None';
180	
181	  const statusEmoji = isReady ? '✅' : '🔄';
182	  const metaLine = [
183	    issueNum ? `<${issueUrl}|Issue #${issueNum}>` : null,
184	    prNum    ? `<${prUrl}|PR #${prNum}>` : null,
185	    `*${status}*`,
186	  ].filter(Boolean).join('  ·  ');
187	
188	  const blocks = [
189	    { type: 'header', text: { type: 'plain_text', text: `${statusEmoji} ${title}`, emoji: true } },
190	    {
191	      type: 'section',
192	      text: { type: 'mrkdwn', text: `${metaLine}\n\`${REPO}\`` },
193	      accessory: { type: 'button', text: { type: 'plain_text', text: 'View Comment' }, url: commentUrl }
194	    },
195	    { type: 'divider' },
196	    {
197	      type: 'markdown',
198	      text: tableLines.join('\n') + `\n\n**Follow-up:** ${followup}`
199	    },
200	    { type: 'divider' },
201	  ];
202	
203	  const actions = [];
204	  if (issueNum) actions.push({ type: 'button', text: { type: 'plain_text', text: `Issue #${issueNum}` }, url: issueUrl });
205	  if (prNum)    actions.push({ type: 'button', text: { type: 'plain_text', text: `Pull Request #${prNum}` }, url: prUrl, style: 'primary' });
206	  if (actions.length) blocks.push({ type: 'actions', elements: actions });
207	
208	  return {
209	    text: `${statusEmoji} ${title} · Issue #${issueNum}`,
210	    blocks
211	  };
212	}
213	
214	// ---------------------------------------------------------------------------
215	// Stage card — compact header + optional detail block
216	// ---------------------------------------------------------------------------
217	
218	function buildStageCard(icon, label, body, num, ghUrl, commentUrl, isIssue, detailFn) {
219	  const refType = isIssue ? 'Issue' : 'PR';
220	  const subtitle = body.match(/^#{1,3}\s+(.+)$/m)?.[1]?.trim() || label;
221	
222	  const blocks = [
223	    {
224	      type: 'section',
225	      text: { type: 'mrkdwn', text: `${icon}  *${label}*  ·  <${ghUrl}|${refType} #${num}>\n_${subtitle}_` },
226	      accessory: { type: 'button', text: { type: 'plain_text', text: 'View Comment' }, url: commentUrl }
227	    }
228	  ];
229	
230	  // Add a rich detail block if we know how to extract meaningful structure from this comment type
231	  const detail = detailFn ? detailFn(body) : null;
232	  if (detail) blocks.push({ type: 'markdown', text: detail });
233	
234	  blocks.push({
235	    type: 'context',
236	    elements: [{ type: 'mrkdwn', text: `\`${REPO}\`  ·  <${ghUrl}|${refType} #${num}>  ·  <${commentUrl}|Open in GitHub>` }]
237	  });
238	
239	  return { text: `${label} — ${refType} #${num}`, blocks };
240	}
241	
242	// ---------------------------------------------------------------------------
243	// Detail extractors — pull 3-4 structured facts from each comment type
244	// ---------------------------------------------------------------------------
245	
246	function buildGroomingDetail(body) {
247	  const effort     = body.match(/\*\*[Ee]ffort[^:]*:\*\*\s*([^\n,|]+)/)?.[1]?.trim()
248	                  || body.match(/effort[:\s]+([XxSsMmLl]+)/)?.[1]?.trim() || null;
249	  const risk       = body.match(/\*\*[Rr]isk[^:]*:\*\*\s*([^\n,|]+)/)?.[1]?.trim()
250	                  || body.match(/risk[_\s]*level[:\s]+([A-Z]+)/i)?.[1]?.trim() || null;
251	  const confidence = body.match(/\*\*[Cc]onfidence[^:]*:\*\*\s*([^\n,|]+)/)?.[1]?.trim()
252	                  || body.match(/confidence[:\s]+([A-Z]+)/i)?.[1]?.trim() || null;
253	  const openQ      = (body.match(/open[_ ]questions?/gi) || []).length > 0
254	                  ? (body.match(/^\d+\.\s+/gm) || []).length || null
255	                  : null;
256	
257	  const parts = [];
258	  if (effort)     parts.push(`**Effort:** ${effort}`);
259	  if (risk)       parts.push(`**Risk:** ${risk}`);
260	  if (confidence) parts.push(`**Confidence:** ${confidence}`);
261	  const meta = parts.join('  ·  ');
262	
263	  const lines = [meta].filter(Boolean);
264	  if (openQ) lines.push(`**Open questions:** ${openQ} documented, proceeding with assumptions`);
265	
266	  return lines.length ? lines.join('\n') : null;
267	}
268	
269	function buildChallengerDetail(body) {
270	  const verdict = body.match(/\*\*(APPROVED|NEEDS_REVISION|BLOCKED)\*\*/)?.[1]
271	               || (body.toLowerCase().includes('approved') ? 'APPROVED' : null);
272	  const must = (body.match(/MUST_HAVE/g) || []).length;
273	  const should = (body.match(/SHOULD_HAVE/g) || []).length;
274	
275	  const lines = [];
276	  if (verdict) lines.push(`**Verdict:** ${verdict}`);
277	  if (must)    lines.push(`**Must-have findings:** ${must}`);
278	  if (should)  lines.push(`**Should-have findings:** ${should}`);
279	  return lines.length ? lines.join('  ·  ') : null;
280	}
281	
282	function buildReviewDetail(body) {
283	  const verdict  = body.match(/\*\*(PASS|REQUEST_CHANGES|APPROVED)\*\*/)?.[1]
284	                || (body.toLowerCase().includes('approved') ? 'APPROVED'
285	                  : body.toLowerCase().includes('request') ? 'REQUEST_CHANGES' : null);
286	  const critical = (body.match(/CRITICAL/g) || []).length;
287	  const high     = (body.match(/\bHIGH\b/g) || []).length;
288	
289	  const lines = [];
290	  if (verdict)  lines.push(`**Verdict:** ${verdict}`);
291	  if (critical) lines.push(`**Critical blockers:** ${critical}`);
292	  if (high)     lines.push(`**High blockers:** ${high}`);
293	  return lines.length ? lines.join('  ·  ') : null;
294	}
295	
296	function buildQADetail(body) {
297	  // Try to extract AC results as a task list
298	  const acLines = [];
299	  for (const line of body.split('\n')) {
300	    const m = line.match(/AC\d+[^—–-]*[—–-]\s*(.+)/);
301	    if (!m) continue;
302	    const passed = line.includes('PASS') || line.includes('✅');
303	    acLines.push(`- [${passed ? 'x' : ' '}] ${m[1].trim()}`);
304	    if (acLines.length >= 8) break; // cap at 8 items
305	  }
306	  return acLines.length ? acLines.join('\n') : null;
307	}
308	
309	// ---------------------------------------------------------------------------
310	// Generic card — fallback
311	// ---------------------------------------------------------------------------
312	
313	function buildGenericCard(body, num, ghUrl, commentUrl, isIssue) {
314	  const refType = isIssue ? 'Issue' : 'PR';
315	  const title   = body.match(/^#{1,3}\s+(.+)$/m)?.[1]?.trim() || 'Pipeline Comment';
316	
317	  return {
318	    text: `AI Pipeline · ${refType} #${num}`,
319	    blocks: [
320	      {
321	        type: 'section',
322	        text: { type: 'mrkdwn', text: `🤖  *${title}*\n<${ghUrl}|${refType} #${num}> · \`${REPO}\`` },
323	        accessory: { type: 'button', text: { type: 'plain_text', text: 'View Comment' }, url: commentUrl }
324	      },
325	      { type: 'context', elements: [{ type: 'mrkdwn', text: `<${commentUrl}|View on GitHub>` }] }
326	    ]
327	  };
328	}
329	
330	// ---------------------------------------------------------------------------
331	// Markdown table parser
332	// ---------------------------------------------------------------------------
333	
334	function parseMarkdownTable(body) {
335	  const rows = [];
336	  for (const line of body.split('\n')) {
337	    if (!line.startsWith('|')) continue;
338	    if (/^\|[\s\-:|]+\|$/.test(line)) continue;
339	    const cells = line.split('|').slice(1, -1).map(c => c.trim());
340	    if (cells[0]?.toLowerCase() === 'stage') continue;
341	    if (cells.length >= 2) rows.push(cells);
342	  }
343	  return rows;
344	}
345	
346	// ---------------------------------------------------------------------------
347	// Extract issue number from PR comment body text
348	// ---------------------------------------------------------------------------
349	
350	function extractIssueFromBody(body) {
351	  return body.match(/[Ii]ssue\s*[:#]?\s*#?(\d+)/)?.[1] || null;
352	}
353	
354	// ---------------------------------------------------------------------------
355	// Thread persistence — one Slack thread per GitHub issue
356	// ---------------------------------------------------------------------------
357	
358	function getThreadTs(issueNum) {
359	  try { return fs.readFileSync(path.join(THREADS_DIR, `issue-${issueNum}.ts`), 'utf8').trim(); }
360	  catch { return null; }
361	}
362	
363	function saveThreadTs(issueNum, ts) {
364	  try {
365	    fs.mkdirSync(THREADS_DIR, { recursive: true });
366	    fs.writeFileSync(path.join(THREADS_DIR, `issue-${issueNum}.ts`), ts);
367	  } catch (e) {
368	    process.stderr.write(`slack-notify: could not save thread ts: ${e.message}\n`);
369	  }
370	}
371	
372	// ---------------------------------------------------------------------------
373	// Tool output extraction
374	// ---------------------------------------------------------------------------
375	
376	function getOutput(data) {
377	  const content = data.tool_response?.content;
378	  if (Array.isArray(content)) return content.map(c => c.text || '').join('');
379	  return data.tool_response?.output || data.tool_result?.output || '';
380	}
381	
382	// ---------------------------------------------------------------------------
383	// Body extraction from raw bash command (heredoc / double-quoted / single-quoted)
384	// ---------------------------------------------------------------------------
385	
386	function extractBody(command) {
387	  let m = command.match(/(?:--body|-b)\s+"?\$\(cat\s+<<['"]?(\w+)['"]?\n([\s\S]*?)\n\1/);
388	  if (m) return m[2].trim();
389	
390	  m = command.match(/(?:--body|-b)\s+"((?:[^"\\]|\\.)*)"/s);
391	  if (m && !m[1].trimStart().startsWith('$(')) {
392	    return m[1].replace(/\\n/g, '\n').replace(/\\"/g, '"').trim();
393	  }
394	
395	  m = command.match(/(?:--body|-b)\s+'((?:[^'\\]|\\.)*)'/s);
396	  if (m) return m[1].trim();
397	
398	  return '';
399	}
400	
401	// ---------------------------------------------------------------------------
402	// Slack API — returns ts on success (used for threading)
403	// ---------------------------------------------------------------------------
404	
405	async function postToSlack(payload) {
406	  const body = JSON.stringify(payload);
407	  return new Promise(resolve => {
408	    const req = https.request(
409	      {
410	        hostname: 'slack.com',
411	        path:     '/api/chat.postMessage',
412	        method:   'POST',
413	        headers:  {
414	          'Content-Type':   'application/json',
415	          'Authorization':  `Bearer ${SLACK_TOKEN}`,
416	          'Content-Length': Buffer.byteLength(body)
417	        }
418	      },
419	      res => {
420	        let respData = '';
421	        res.on('data', d => { respData += d; });
422	        res.on('end', () => {
423	          try {
424	            const resp = JSON.parse(respData);
425	            if (!resp.ok) {
426	              process.stderr.write(`slack-notify: Slack API error: ${resp.error}\n`);
427	              resolve(null);
428	            } else {
429	              resolve(resp.ts || null);
430	            }
431	          } catch (e) {
432	            process.stderr.write(`slack-notify: response parse error: ${e.message}\n`);
433	            resolve(null);
434	          }
435	        });
436	      }
437	    );
438	    req.on('error', e => { process.stderr.write(`slack-notify: network error: ${e.message}\n`); resolve(null); });
439	    req.setTimeout(8000, () => { req.destroy(); resolve(null); });
440	    req.write(body);
441	    req.end();
442	  });
443	}
